// ============================================================================
// 2. ANIMATION HOOKS & FRAMER-MOTION / GSAP SCROLLTRIGGER ENGINE
// ============================================================================
function useScrollReveal(threshold = 0.16) {
  const ref = useRef<HTMLDivElement | null>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
          }
        });
      },
      { threshold, rootMargin: '0px 0px -40px 0px' }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [threshold]);

  return { ref, isVisible };
}

// Staggered text reveal component (Framer Motion style word-by-word / char-by-char)
const AnimatedHeading: React.FC<{
  text: string;
  className?: string;
  delayMs?: number;
  staggerMs?: number;
  isVisible?: boolean;
  mode?: 'words' | 'chars';
}> = ({ text, className = '', delayMs = 0, staggerMs = 45, isVisible = true, mode = 'chars' }) => {
  const tokens = mode === 'words' ? text.split(' ') : Array.from(text);
  return (
    <span className={`inline-block ${className}`} aria-label={text}>
      {tokens.map((token, idx) => (
        <span
          key={idx}
          aria-hidden="true"
          style={{
            display: 'inline-block',
            whiteSpace: token === ' ' ? 'pre' : 'normal',
            opacity: isVisible ? 1 : 0,
            transform: isVisible
              ? 'translate3d(0, 0px, 0) scale(1)'
              : 'translate3d(0, 14px, 0) scale(0.94)',
            transition: `opacity 650ms cubic-bezier(0.22, 1, 0.36, 1) ${
              delayMs + idx * staggerMs
            }ms, transform 650ms cubic-bezier(0.22, 1, 0.36, 1) ${delayMs + idx * staggerMs}ms`,
          }}
        >
          {token}
          {mode === 'words' && idx < tokens.length - 1 ? '\u00A0' : ''}
        </span>
      ))}
    </span>
  );
};

