// ============================================================================
// 4. WEB AUDIO API ROMANTIC MUSIC BOX SYNTHESIZER (Fallback + Tracks 2 & 3)
// ============================================================================
class RomanticSynthEngine {
  private ctx: AudioContext | null = null;
  private timer: number | null = null;
  private step = 0;

  public start(notes: number[]) {
    this.stop();
    const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioCtx) return;
    if (!this.ctx) {
      this.ctx = new AudioCtx();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    this.step = 0;
    const playStep = () => {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const freq = notes[this.step % notes.length];
      const osc = this.ctx.createOscillator();
      const sub = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'sine';
      sub.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now);
      sub.frequency.setValueAtTime(freq * 0.5, now);

      gain.gain.setValueAtTime(0.001, now);
      gain.gain.exponentialRampToValueAtTime(0.08, now + 0.04);
      gain.gain.exponentialRampToValueAtTime(0.0008, now + 1.15);

      osc.connect(gain);
      sub.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      sub.start(now);
      osc.stop(now + 1.2);
      sub.stop(now + 1.2);

      this.step += 1;
    };
    playStep();
    this.timer = window.setInterval(playStep, 550);
  }

  public stop() {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

