// SECTION 08 — CLOSING SECTION (Exact match to frame_058.png bottom)
const ClosingSection: React.FC<{ config: InvitationConfig }> = ({ config }) => {
  const { ref, isVisible } = useScrollReveal(0.15);

  return (
    <footer
      id="section-closing"
      ref={ref}
      className="relative w-full pt-6 pb-20 px-4 text-center overflow-hidden select-none"
      style={{ backgroundColor: 'var(--color-background)' }}
    >
      <div className="max-w-[400px] mx-auto flex flex-col items-center">
        {/* Main Closing Heading: "SEE YOU AT OUR ENGAGEMENT DAY!" */}
        <h2
          className="text-2xl sm:text-3xl font-bold uppercase leading-[1.15] tracking-wider"
          style={{
            color: 'var(--color-strawberry)',
            fontFamily: "'Patrick Hand', 'Amatic SC', cursive",
          }}
        >
          <AnimatedHeading
            text={config.closing.mainHeadingLine1}
            isVisible={isVisible}
            delayMs={100}
            staggerMs={35}
          />
          <br />
          <AnimatedHeading
            text={config.closing.mainHeadingLine2}
            isVisible={isVisible}
            delayMs={450}
            staggerMs={35}
          />
        </h2>

        {/* WITH LOVE + GROOM & BRIDE NAME */}
        <div
          className="mt-8 space-y-1 transition-all duration-700 delay-300"
          style={{
            opacity: isVisible ? 1 : 0,
            transform: isVisible ? 'translateY(0)' : 'translateY(10px)',
          }}
        >
          <p
            className="text-xs sm:text-sm font-bold tracking-[0.16em] uppercase"
            style={{
              color: 'var(--color-matcha)',
              fontFamily: "'Amatic SC', 'Patrick Hand', cursive",
            }}
          >
            {config.closing.subHeading}
          </p>
          <p
            className="text-xl sm:text-2xl font-bold tracking-wider uppercase"
            style={{
              color: 'var(--color-strawberry)',
              fontFamily: "'Patrick Hand', 'Amatic SC', cursive",
            }}
          >
            {config.closing.coupleSignature}
          </p>
        </div>

        {/* Delicate Pink Line with Center Heart (Matches frame_058.png bottom) */}
        <div className="my-4 w-48 flex items-center justify-center gap-2">
          <div className="h-[1px] flex-1 bg-[#F5B6CC]" />
          <HandDrawnHeart size={12} strokeColor="#EE5B91" fillColor="#F5B6CC" />
          <div className="h-[1px] flex-1 bg-[#F5B6CC]" />
        </div>

        {/* Handwritten Footer Credit */}
        <p
          className="text-xs italic tracking-wide transition-opacity duration-700 delay-500"
          style={{
            color: 'var(--color-matcha)',
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            opacity: isVisible ? 0.85 : 0,
          }}
        >
          {config.closing.footerCredit}
        </p>
      </div>
    </footer>
  );
};

// ============================================================================
// 6. MAIN APPLICATION COMPONENT
// ============================================================================
const NAV_ITEMS = [
  { id: 'section-opening', label: 'Home', icon: House },
  { id: 'section-save-the-date', label: 'Date', icon: Calendar },
  { id: 'section-couple', label: 'Couple', icon: Heart },
  { id: 'section-details', label: 'Acara', icon: MapPin },
  { id: 'section-gallery', label: 'Galeri', icon: Camera },
  { id: 'section-rsvp', label: 'RSVP', icon: MessageSquareHeart },
];

export default function App() {
  const [config, setConfig] = useState<InvitationConfig>(DEFAULT_CONFIG);
  const [isOpened, setIsOpened] = useState<boolean>(false);
  const [currentTrackIdx, setCurrentTrackIdx] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [progressSec, setProgressSec] = useState<number>(0);
  const [durationSec, setDurationSec] = useState<number>(20);
  const [wishes, setWishes] = useState<WishItem[]>(DEFAULT_CONFIG.rsvp.initialWishes);

  // Modals & Drawers
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const [activeSection, setActiveSection] = useState<string>(NAV_ITEMS[0].id);
  const touchStartX = useRef(0);
  const [showMapModal, setShowMapModal] = useState<boolean>(false);
  const [showCalendarModal, setShowCalendarModal] = useState<boolean>(false);
  const [showEditorDrawer, setShowEditorDrawer] = useState<boolean>(false);
  const [copiedLink, setCopiedLink] = useState<boolean>(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const synthRef = useRef<RomanticSynthEngine | null>(null);

  // Load saved wishes from localStorage safely
  useEffect(() => {
    try {
      const saved = localStorage.getItem('strawberry_matcha_wishes_v1');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setWishes(parsed);
        }
      }
    } catch {
      // Ignore storage restrictions in sandboxed iframe
    }
  }, []);

  // Lock page scroll until the invitation is opened, and while the lightbox is up
  useEffect(() => {
    // Restored scroll position after a reload would otherwise strand the guest mid-page while locked
    if (!isOpened) window.scrollTo(0, 0);
    document.documentElement.style.overflow = !isOpened || lightboxIndex !== null ? 'hidden' : '';
  }, [isOpened, lightboxIndex]);

  // Highlight the bottom-dock item for the section in the middle of the viewport
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => entries.forEach((e) => e.isIntersecting && setActiveSection(e.target.id)),
      { rootMargin: '-45% 0px -50% 0px' }
    );
    NAV_ITEMS.forEach(({ id }) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, []);

  // Lightbox keyboard controls
  const galleryCount = config.assets.galleryPhotos.length;
  const stepLightbox = (dir: number) =>
    setLightboxIndex((i) => (i === null ? null : (i + dir + galleryCount) % galleryCount));
  useEffect(() => {
    if (lightboxIndex === null) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setLightboxIndex(null);
      if (e.key === 'ArrowLeft') stepLightbox(-1);
      if (e.key === 'ArrowRight') stepLightbox(1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  // Manage Audio / Synthesizer Playback
  useEffect(() => {
    if (!synthRef.current) {
      synthRef.current = new RomanticSynthEngine();
    }
    const track = config.music.tracks[currentTrackIdx];
    const audioEl = audioRef.current;

    if (!isPlaying) {
      if (audioEl) audioEl.pause();
      synthRef.current.stop();
      return;
    }

    if (track?.audioSrc && audioEl) {
      synthRef.current.stop();
      if (audioEl.src !== track.audioSrc) {
        audioEl.src = track.audioSrc;
      }
      audioEl.play().catch(() => {
        // Fallback to Web Audio synth if audio element is blocked
        synthRef.current?.start([523.25, 659.25, 783.99, 1046.5, 880.0, 783.99]);
      });
    } else if (track?.synthNotes) {
      if (audioEl) audioEl.pause();
      synthRef.current.start(track.synthNotes);
    }

    return () => {
      synthRef.current?.stop();
    };
  }, [isPlaying, currentTrackIdx, config.music.tracks]);

  // Synthetic progress timer when playing synth tracks
  useEffect(() => {
    const track = config.music.tracks[currentTrackIdx];
    if (!isPlaying || track?.audioSrc) return;
    setDurationSec(165);
    const id = window.setInterval(() => {
      setProgressSec((prev) => (prev + 1) % 165);
    }, 1000);
    return () => clearInterval(id);
  }, [isPlaying, currentTrackIdx, config.music.tracks]);

  const handleOpenInvitation = () => {
    setIsOpened(true);
    if (!isPlaying) {
      setIsPlaying(true);
    }
    window.setTimeout(() => {
      const nextEl = document.getElementById('section-save-the-date');
      if (nextEl) {
        nextEl.scrollIntoView({ behavior: 'smooth' });
      }
    }, 120);
  };

  const handleTogglePlay = () => {
    setIsPlaying((prev) => !prev);
  };

  const handlePrevTrack = () => {
    setProgressSec(0);
    setCurrentTrackIdx((prev) =>
      prev === 0 ? config.music.tracks.length - 1 : prev - 1
    );
    setIsPlaying(true);
  };

  const handleNextTrack = () => {
    setProgressSec(0);
    setCurrentTrackIdx((prev) => (prev + 1) % config.music.tracks.length);
    setIsPlaying(true);
  };

  const handleSeek = (newSec: number) => {
    setProgressSec(newSec);
    if (audioRef.current && config.music.tracks[currentTrackIdx]?.audioSrc) {
      audioRef.current.currentTime = newSec;
    }
  };

  const handleAddWish = (newWish: Omit<WishItem, 'id' | 'createdAt'>) => {
    const created: WishItem = {
      ...newWish,
      id: `w-${Date.now()}`,
      createdAt: 'Baru saja',
    };
    setWishes((prev) => {
      const updated = [created, ...prev];
      try {
        localStorage.setItem('strawberry_matcha_wishes_v1', JSON.stringify(updated));
      } catch {
        // Ignore storage error
      }
      return updated;
    });
  };

  const handlePhotoUpload = (index: number, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        const dataUrl = reader.result;
        setConfig((prev) => {
          const nextPhotos = [...prev.assets.galleryPhotos];
          nextPhotos[index] = dataUrl;
          return {
            ...prev,
            assets: { ...prev.assets, galleryPhotos: nextPhotos },
          };
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCopyInvitationInfo = () => {
    const summaryText = `${config.couple.groomFullName} & ${config.couple.brideFullName} Engagement — ${config.event.dayAndDate} (${config.event.timeRange}) at ${config.event.venueName}, ${config.event.venueAddressLine1}`;
    try {
      navigator.clipboard.writeText(summaryText);
    } catch {
      const ta = document.createElement('textarea');
      ta.value = summaryText;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }
    setCopiedLink(true);
    window.setTimeout(() => setCopiedLink(false), 2500);
  };

  return (
    <div
      className="min-h-screen w-full relative flex items-start justify-center"
      style={{ backgroundColor: '#E4E6D6' }}
    >
      {/* Scroll Progress Bar (CSS scroll-driven animation, hidden where unsupported) */}
      <div aria-hidden="true" className="scroll-progress fixed top-0 inset-x-0 h-1 z-50" />

      {/* Ambient Falling Petals (after opening) */}
      {isOpened && (
        <div aria-hidden="true" className="fixed inset-0 z-30 pointer-events-none overflow-hidden">
          {Array.from({ length: 10 }, (_, i) => (
            <span
              key={i}
              className="petal"
              style={{
                left: `${(i * 37 + 5) % 100}%`,
                backgroundColor: i % 3 ? '#F5B6CC' : '#C6C59C',
                animationDuration: `${10 + (i % 4) * 2.5}s`,
                animationDelay: `${i * 1.4}s`,
              }}
            />
          ))}
        </div>
      )}

      {/* Hidden Real Audio Element */}
      <audio
        ref={audioRef}
        src={config.music.tracks[0]?.audioSrc}
        loop
        onTimeUpdate={() => {
          if (audioRef.current) {
            setProgressSec(audioRef.current.currentTime);
          }
        }}
        onLoadedMetadata={() => {
          if (audioRef.current && audioRef.current.duration) {
            setDurationSec(audioRef.current.duration);
          }
        }}
      />

      {/* Desktop Cover Panel (lg+): sticky photo beside the invitation column */}
      <aside className="hidden lg:flex sticky top-0 h-screen flex-1 overflow-hidden items-end">
        <img
          src={config.assets.coverPhoto}
          alt=""
          className="cover-kenburns absolute inset-0 w-full h-full object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#2E2F1C]/85 via-[#2E2F1C]/25 to-transparent" />
        <div className="cover-text-in relative p-12 xl:p-16 text-white">
          <p
            className="uppercase tracking-[0.35em] text-sm"
            style={{ fontFamily: "'Patrick Hand', cursive" }}
          >
            The {config.event.title} of
          </p>
          <h2
            className="capitalize leading-none mt-3 text-7xl xl:text-8xl"
            style={{ fontFamily: "'Sacramento', cursive" }}
          >
            {config.couple.groomShortName.toLowerCase()} &amp; {config.couple.brideShortName.toLowerCase()}
          </h2>
          <div
            className="mt-5 flex items-center gap-3 text-lg tracking-[0.2em]"
            style={{ fontFamily: "'Patrick Hand', cursive" }}
          >
            <span>{config.event.dateDots}</span>
            <span className="w-10 h-px bg-white/70" />
            <span className="text-sm tracking-wider">{config.event.venueName}</span>
          </div>
        </div>
      </aside>

      {/* Invitation Column (Mobile-First 480px Editorial Proportions) */}
      <main
        className="w-full max-w-[480px] shrink-0 min-h-screen shadow-2xl overflow-x-clip relative"
        style={{ backgroundColor: 'var(--color-background)' }}
      >
        {/* Sticky Top Toolbar */}
        <div className="sticky top-3 z-40 h-0">
          <div className="px-3 flex items-center justify-between pointer-events-none">
            <div className="pointer-events-auto flex items-center gap-1.5 bg-[#F0F1E6]/90 backdrop-blur-md border border-[#C6C59C] px-2.5 py-1 rounded-full shadow-sm">
              <span
                className="w-2 h-2 rounded-full"
                style={{ backgroundColor: 'var(--color-strawberry)' }}
              />
              <span
                className="text-xs font-bold tracking-wider"
                style={{ color: 'var(--color-matcha)', fontFamily: "'Patrick Hand', cursive" }}
              >
                {config.couple.groomShortName} &amp; {config.couple.brideShortName}
              </span>
            </div>

            <div className="pointer-events-auto flex items-center gap-1.5">
              <button
                type="button"
                onClick={handleCopyInvitationInfo}
                title="Salin info undangan"
                className="bg-[#F0F1E6]/90 backdrop-blur-md border border-[#C6C59C] text-[#858653] hover:text-[#EE5B91] px-2.5 py-1 rounded-full text-xs font-bold shadow-sm cursor-pointer flex items-center gap-1 transition-colors"
                style={{ fontFamily: "'Patrick Hand', cursive" }}
              >
                {copiedLink ? <Check className="w-3.5 h-3.5 text-[#EE5B91]" /> : <Share2 className="w-3.5 h-3.5" />}
                <span>{copiedLink ? 'Tersalin' : 'Share'}</span>
              </button>

              <button
                type="button"
                onClick={() => setShowEditorDrawer(true)}
                title="Edit Data Undangan (Config)"
                className="bg-[#F0F1E6]/90 backdrop-blur-md border border-[#C6C59C] text-[#858653] hover:text-[#EE5B91] px-2.5 py-1 rounded-full text-xs font-bold shadow-sm cursor-pointer flex items-center gap-1 transition-colors"
                style={{ fontFamily: "'Patrick Hand', cursive" }}
              >
                <Edit3 className="w-3.5 h-3.5" />
                <span>Customize</span>
              </button>
            </div>
          </div>
        </div>

        {/* SECTION 01 — OPENING INVITATION */}
        <OpeningInvitation
          config={config}
          isOpened={isOpened}
          onOpenInvitation={handleOpenInvitation}
        />

        {/* SECTION 02 — SAVE THE DATE & SECTION 03 — MUSIC PLAYER */}
        <SaveTheDateAndMusic
          config={config}
          currentTrackIdx={currentTrackIdx}
          isPlaying={isPlaying}
          progressSec={progressSec}
          durationSec={durationSec}
          onTogglePlay={handleTogglePlay}
          onPrevTrack={handlePrevTrack}
          onNextTrack={handleNextTrack}
          onSeek={handleSeek}
          onOpenCalendarModal={() => setShowCalendarModal(true)}
        />

        {/* SECTION 04 — THE COUPLE */}
        <CoupleProfile config={config} />

        {/* SECTION 05 — ENGAGEMENT DETAILS */}
        <EngagementDetails
          config={config}
          onToggleMapModal={() => setShowMapModal(true)}
        />

        {/* SECTION 06 — LOVE STORY */}
        <LoveStory config={config} />

        {/* SECTION 07 — PHOTO GALLERY */}
        <PhotoGallery config={config} onSelectPhoto={setLightboxIndex} />

        {/* INTERACTIVE RSVP & GUEST WISHES WALL */}
        <RSVPFormSection
          config={config}
          wishes={wishes}
          onAddWish={handleAddWish}
        />

        {/* SECTION 08 — CLOSING SECTION */}
        <ClosingSection config={config} />

        {/* Bottom Section Navigation Dock + Music Toggle */}
        {isOpened && (
          <nav aria-label="Navigasi undangan" className="sticky bottom-3 z-40 h-0">
            <div className="dock-in absolute bottom-0 inset-x-3 flex items-center gap-0.5 p-1.5 rounded-full bg-[#F0F1E6]/90 backdrop-blur-md border border-[#C6C59C] shadow-lg">
              {NAV_ITEMS.map(({ id, label, icon: Icon }) => {
                const active = activeSection === id;
                return (
                  <a
                    key={id}
                    href={`#${id}`}
                    aria-current={active ? 'location' : undefined}
                    className="flex-1 min-w-0 flex flex-col items-center gap-0.5 py-1 rounded-full text-[10px] font-bold transition-colors duration-300"
                    style={{
                      color: active ? '#FFFFFF' : 'var(--color-matcha)',
                      backgroundColor: active ? 'var(--color-strawberry)' : 'transparent',
                      fontFamily: "'Patrick Hand', cursive",
                    }}
                  >
                    <Icon className="w-4 h-4" />
                    <span>{label}</span>
                  </a>
                );
              })}
              <button
                type="button"
                onClick={handleTogglePlay}
                aria-label={isPlaying ? 'Mute background music' : 'Play background music'}
                className={`w-10 h-10 shrink-0 rounded-full border-2 border-white flex items-center justify-center cursor-pointer active:scale-95 transition-colors ${
                  isPlaying ? 'music-pulse' : ''
                }`}
                style={{
                  backgroundColor: isPlaying ? 'var(--color-strawberry)' : 'var(--color-matcha)',
                  color: '#FFFFFF',
                }}
              >
                {isPlaying ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
              </button>
            </div>
          </nav>
        )}
      </main>

      {/* ==================================================================== */}
      {/* MODAL 1: GALLERY LIGHTBOX (Swipe / Arrow Keys) & CUSTOM UPLOAD       */}
      {/* ==================================================================== */}
      {lightboxIndex !== null && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label="Galeri foto"
          className="lightbox-in fixed inset-0 z-50 bg-[#2E2F1C]/90 backdrop-blur-sm flex flex-col items-center justify-center gap-4 p-4"
          onClick={() => setLightboxIndex(null)}
          onTouchStart={(e) => (touchStartX.current = e.touches[0].clientX)}
          onTouchEnd={(e) => {
            const dx = e.changedTouches[0].clientX - touchStartX.current;
            if (Math.abs(dx) > 50) stepLightbox(dx < 0 ? 1 : -1);
          }}
        >
          <button
            type="button"
            onClick={() => setLightboxIndex(null)}
            aria-label="Close photo preview"
            className="absolute top-4 right-4 w-9 h-9 rounded-full bg-[#EE5B91] text-white flex items-center justify-center cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>

          <figure
            key={lightboxIndex}
            className="lightbox-photo-in relative max-w-md w-full bg-white p-3 pb-10 rounded-sm shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <img
              src={config.assets.galleryPhotos[lightboxIndex]}
              alt={`Foto ${lightboxIndex + 1}`}
              className="w-full max-h-[65vh] object-contain bg-[#F0F1E6]"
            />
            <figcaption
              className="absolute bottom-2 inset-x-0 text-center text-lg"
              style={{ color: 'var(--color-strawberry)', fontFamily: "'Caveat', cursive" }}
            >
              {lightboxIndex + 1} / {galleryCount}
            </figcaption>
          </figure>

          <div className="flex items-center gap-3" onClick={(e) => e.stopPropagation()}>
            <button
              type="button"
              onClick={() => stepLightbox(-1)}
              aria-label="Foto sebelumnya"
              className="w-10 h-10 rounded-full bg-white/90 text-[#EE5B91] flex items-center justify-center cursor-pointer hover:scale-105 transition-transform"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
            <label
              className="py-2 px-4 rounded-full text-white text-xs font-bold cursor-pointer flex items-center gap-1.5 shadow"
              style={{ backgroundColor: 'var(--color-matcha)' }}
            >
              <Upload className="w-3.5 h-3.5" />
              <span>Ganti dengan Foto Asli</span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => handlePhotoUpload(lightboxIndex, e)}
              />
            </label>
            <button
              type="button"
              onClick={() => stepLightbox(1)}
              aria-label="Foto berikutnya"
              className="w-10 h-10 rounded-full bg-white/90 text-[#EE5B91] flex items-center justify-center cursor-pointer hover:scale-105 transition-transform"
            >
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* ==================================================================== */}
      {/* MODAL 2: VENUE MAP & DIRECTIONS PREVIEW                              */}
      {/* ==================================================================== */}
      {showMapModal && (
        <div
          className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setShowMapModal(false)}
        >
          <div
            className="relative max-w-md w-full rounded-3xl p-6 shadow-2xl border-2 text-center"
            style={{
              backgroundColor: 'var(--color-background)',
              borderColor: 'var(--color-matcha)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              onClick={() => setShowMapModal(false)}
              aria-label="Close map modal"
              className="absolute top-3.5 right-3.5 w-8 h-8 rounded-full bg-[#858653] text-white flex items-center justify-center cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>

            <MapPin className="w-8 h-8 mx-auto text-[#EE5B91] mb-2" />
            <h3
              className="text-2xl font-bold uppercase tracking-wider"
              style={{ color: 'var(--color-strawberry)', fontFamily: "'Amatic SC', cursive" }}
            >
              {config.event.venueName}
            </h3>
            <p
              className="text-xs sm:text-sm font-semibold mt-1"
              style={{ color: 'var(--color-matcha)', fontFamily: "'Patrick Hand', cursive" }}
            >
              {config.event.venueAddressLine1}, {config.event.venueAddressLine2}
            </p>

            {/* Stylized Illustrated Map Card */}
            <div
              className="my-4 p-4 rounded-2xl border-2 text-left space-y-2"
              style={{
                backgroundColor: '#FAFBF6',
                borderColor: 'var(--color-pink-light)',
              }}
            >
              <div className="flex items-center justify-between text-xs font-bold" style={{ color: 'var(--color-matcha)' }}>
                <span>Hari &amp; Tanggal:</span>
                <span style={{ color: 'var(--color-strawberry)' }}>{config.event.dayAndDate}</span>
              </div>
              <div className="flex items-center justify-between text-xs font-bold" style={{ color: 'var(--color-matcha)' }}>
                <span>Waktu Acara:</span>
                <span style={{ color: 'var(--color-strawberry)' }}>{config.event.timeRange}</span>
              </div>
              <div className="flex items-center justify-between text-xs font-bold" style={{ color: 'var(--color-matcha)' }}>
                <span>Patokan Lokasi:</span>
                <span>Pusat Kota Tegal (Jl. Yos Sudarso No.10)</span>
              </div>
            </div>

            <a
              href={config.event.googleMapsUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="w-full py-2.5 rounded-full text-white font-bold text-sm uppercase tracking-wider shadow inline-flex items-center justify-center gap-2"
              style={{ backgroundColor: 'var(--color-strawberry)', fontFamily: "'Patrick Hand', cursive" }}
            >
              <MapPin className="w-4 h-4" />
              Buka Navigasi Google Maps
            </a>
          </div>
        </div>
      )}

      {/* ==================================================================== */}
      {/* MODAL 3: SAVE THE DATE CALENDAR REMINDER                             */}
      {/* ==================================================================== */}
      {showCalendarModal && (
        <div
          className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setShowCalendarModal(false)}
        >
          <div
            className="relative max-w-sm w-full rounded-3xl p-6 shadow-2xl border-2 text-center"
            style={{
              backgroundColor: 'var(--color-background)',
              borderColor: 'var(--color-strawberry)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              onClick={() => setShowCalendarModal(false)}
              aria-label="Close calendar modal"
              className="absolute top-3.5 right-3.5 w-8 h-8 rounded-full bg-[#EE5B91] text-white flex items-center justify-center cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>

            <Calendar className="w-8 h-8 mx-auto text-[#EE5B91] mb-2" />
            <h3
              className="text-2xl font-bold uppercase tracking-wider"
              style={{ color: 'var(--color-strawberry)', fontFamily: "'Amatic SC', cursive" }}
            >
              Save The Date — {config.event.dateDots}
            </h3>
            <p
              className="text-xs sm:text-sm font-semibold mt-1 mb-4"
              style={{ color: 'var(--color-matcha)', fontFamily: "'Patrick Hand', cursive" }}
            >
              Simpan pengingat acara pertunangan {config.couple.groomShortName} &amp; {config.couple.brideShortName} ke kalender Anda.
            </p>

            <a
              href={`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(
                `Engagement of ${config.couple.groomFullName} & ${config.couple.brideFullName}`
              )}&dates=20261116T053000Z/20261116T100000Z&details=${encodeURIComponent(
                config.loveStory.paragraphs[0]
              )}&location=${encodeURIComponent(
                `${config.event.venueName}, ${config.event.venueAddressLine1}`
              )}`}
              target="_blank"
              rel="noopener noreferrer"
              className="w-full py-2.5 rounded-full text-white font-bold text-sm uppercase tracking-wider shadow inline-flex items-center justify-center gap-2"
              style={{ backgroundColor: 'var(--color-matcha)', fontFamily: "'Patrick Hand', cursive" }}
            >
              <Calendar className="w-4 h-4" />
              Simpan ke Google Calendar
            </a>
          </div>
        </div>
      )}

      {/* ==================================================================== */}
      {/* DRAWER 4: CENTRALIZED CONFIGURATION LIVE EDITOR                      */}
      {/* ==================================================================== */}
      {showEditorDrawer && (
        <div
          className="fixed inset-0 z-50 bg-black/50 backdrop-blur-xs flex justify-end"
          onClick={() => setShowEditorDrawer(false)}
        >
          <div
            className="w-full max-w-md h-full overflow-y-auto p-6 shadow-2xl border-l-2 space-y-4"
            style={{
              backgroundColor: 'var(--color-background)',
              borderColor: 'var(--color-matcha)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between pb-3 border-b border-[#C6C59C]">
              <div>
                <h3
                  className="text-2xl font-bold uppercase tracking-wider"
                  style={{ color: 'var(--color-strawberry)', fontFamily: "'Amatic SC', cursive" }}
                >
                  Invitation Config Editor
                </h3>
                <p className="text-xs" style={{ color: 'var(--color-matcha)' }}>
                  Ubah nama pasangan, tanggal, lokasi, &amp; cerita secara langsung.
                </p>
              </div>
              <button
                type="button"
                onClick={() => setShowEditorDrawer(false)}
                aria-label="Close config editor"
                className="w-8 h-8 rounded-full bg-[#858653] text-white flex items-center justify-center cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="space-y-3 text-xs" style={{ color: 'var(--color-matcha)' }}>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="font-bold block mb-1">Nama Panggilan Pria</label>
                  <input
                    type="text"
                    value={config.couple.groomShortName}
                    onChange={(e) =>
                      setConfig({
                        ...config,
                        couple: { ...config.couple, groomShortName: e.target.value },
                      })
                    }
                    className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                  />
                </div>
                <div>
                  <label className="font-bold block mb-1">Nama Panggilan Wanita</label>
                  <input
                    type="text"
                    value={config.couple.brideShortName}
                    onChange={(e) =>
                      setConfig({
                        ...config,
                        couple: { ...config.couple, brideShortName: e.target.value },
                      })
                    }
                    className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                  />
                </div>
              </div>

              <div>
                <label className="font-bold block mb-1">Nama Lengkap Pria</label>
                <input
                  type="text"
                  value={config.couple.groomFullName}
                  onChange={(e) =>
                    setConfig({
                      ...config,
                      couple: { ...config.couple, groomFullName: e.target.value },
                    })
                  }
                  className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                />
              </div>

              <div>
                <label className="font-bold block mb-1">Nama Lengkap Wanita</label>
                <input
                  type="text"
                  value={config.couple.brideFullName}
                  onChange={(e) =>
                    setConfig({
                      ...config,
                      couple: { ...config.couple, brideFullName: e.target.value },
                    })
                  }
                  className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="font-bold block mb-1">Hari &amp; Tanggal</label>
                  <input
                    type="text"
                    value={config.event.dayAndDate}
                    onChange={(e) =>
                      setConfig({
                        ...config,
                        event: { ...config.event, dayAndDate: e.target.value },
                      })
                    }
                    className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                  />
                </div>
                <div>
                  <label className="font-bold block mb-1">Tanggal Highlight Kalender</label>
                  <input
                    type="number"
                    min={1}
                    max={31}
                    value={config.event.calendarHighlightDay}
                    onChange={(e) =>
                      setConfig({
                        ...config,
                        event: {
                          ...config.event,
                          calendarHighlightDay: Number(e.target.value) || 16,
                        },
                      })
                    }
                    className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                  />
                </div>
              </div>

              <div>
                <label className="font-bold block mb-1">Nama Venue</label>
                <input
                  type="text"
                  value={config.event.venueName}
                  onChange={(e) =>
                    setConfig({
                      ...config,
                      event: { ...config.event, venueName: e.target.value },
                    })
                  }
                  className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                />
              </div>

              <div>
                <label className="font-bold block mb-1">Paragraf 1 Love Story</label>
                <textarea
                  rows={3}
                  value={config.loveStory.paragraphs[0]}
                  onChange={(e) => {
                    const nextP = [...config.loveStory.paragraphs];
                    nextP[0] = e.target.value;
                    setConfig({
                      ...config,
                      loveStory: { ...config.loveStory, paragraphs: nextP },
                    });
                  }}
                  className="w-full px-2.5 py-1.5 rounded-lg border border-[#C6C59C] bg-white"
                />
              </div>

              <div className="pt-2 flex items-center justify-between gap-2">
                <button
                  type="button"
                  onClick={() => setConfig(DEFAULT_CONFIG)}
                  className="px-4 py-2 rounded-full border border-[#858653] text-[#858653] font-bold flex items-center gap-1.5 cursor-pointer"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  Reset Default
                </button>

                <button
                  type="button"
                  onClick={() => setShowEditorDrawer(false)}
                  className="px-6 py-2 rounded-full text-white font-bold cursor-pointer"
                  style={{ backgroundColor: 'var(--color-strawberry)' }}
                >
                  Simpan Perubahan
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}